final class NativeSpecimenRuntime {
 static void run(GameTestHelper h)throws Exception{var level=h.getLevel();var server=level.getServer();var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original Miner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var data=NativeOreSavedData.get(server);var metrics=List.of("iron","gold","redstone","lapis");if(track.completedQuestIds().contains(NativeSpecimens.QUEST)){h.assertTrue(track.xp()==4200&&track.completedQuestIds().size()==22&&metrics.stream().allMatch(m->data.evidence().count(p.getUUID(),ProfessionRank.MASTER,m)==1)&&ConstructionService.structureIntact(level,mine),"Second JVM restores four native Silk source proofs/Master supply/22earned4200XP/original Mine-Doran");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("NATIVE_SPECIMEN_RESTART_PASSED: four actual native Silk specimens/permanent four-ore delivery/native Master supply receipt/22earned4200XP/oldApp-J-Nether-Master records/Mine-Doran restore");h.succeed();return;}
  h.assertTrue(track.xp()==3600&&track.completedQuestIds().size()==20&&metrics.stream().allMatch(m->data.evidence().count(p.getUUID(),ProfessionRank.MASTER,m)==0),"Starts from actual20proofs, no earlier Journeyman counts relabeled as Master Silk");CreateCraftRuntime.counter(p,mine);for(Item item:List.of(Items.IRON_ORE,Items.GOLD_ORE,Items.REDSTONE_ORE,Items.LAPIS_ORE))h.assertTrue(p.getInventory().add(new ItemStack(item)),"Private wrong-source stock fits");boolean stock=false;try{ProfessionService.review(p,"materials:"+NativeSpecimens.QUEST);}catch(IllegalStateException expected){stock=true;}h.assertTrue(stock,"Full stocked ore cannot fabricate native Silk evidence");for(Item item:List.of(Items.IRON_ORE,Items.GOLD_ORE,Items.REDSTONE_ORE,Items.LAPIS_ORE))p.getInventory().removeItem(p.getInventory().findSlotMatchingItem(new ItemStack(item)),1);
  var seams=new HashMap<String,List<BlockPos>>();metrics.forEach(m->seams.put(m,new ArrayList<>()));for(int x=256;x<260;x+=2)for(int z=176;z<180;z+=2)for(var pos:NativeCopperRuntime.generated(h,p,x,z)){var metric=NativeCopperRuntime.metric(p,pos);if(seams.containsKey(metric))seams.get(metric).add(pos);}for(String metric:metrics)h.assertTrue(seams.get(metric).size()>=3,"Real new marked native specimens exist: "+metric);
  var replaced=seams.get("iron").remove(0);level.setBlock(replaced,Blocks.AIR.defaultBlockState(),3);level.setBlock(replaced,Blocks.IRON_ORE.defaultBlockState(),3);harvest(h,p,replaced,true,false);var normal=seams.get("gold").remove(0);harvest(h,p,normal,false,false);var guard=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("SpecimenClaimGuard".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"SpecGuard");var denied=seams.get("redstone").get(0);ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(guard,denied);BlacksmithRepairRuntime.near(p,denied);var silk=new ItemStack(Items.DIAMOND_PICKAXE);silk.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SILK_TOUCH),1);p.setItemInHand(InteractionHand.MAIN_HAND,silk);h.assertTrue(!p.gameMode.destroyBlock(denied),"Native FTB denied Silk break leaves source intact");ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(p,denied);
  h.runAfterDelay(3,()->guard(h,()->{h.assertTrue(metrics.stream().allMatch(m->data.evidence().count(p.getUUID(),ProfessionRank.MASTER,m)==0),"Replaced Silk block and ordinary gold outputs give no Master source proof");for(String metric:metrics)harvest(h,p,seams.get(metric).get(0),true,metric.equals("lapis"));h.runAfterDelay(3,()->guard(h,()->{h.assertTrue(metrics.stream().allMatch(m->data.evidence().count(p.getUUID(),ProfessionRank.MASTER,m)==1),"Exactly four genuine native Silk source removals, including actual final-durability tool break");CreateCraftRuntime.counter(p,mine);var quote=ProfessionService.review(p,"materials:"+NativeSpecimens.QUEST);ProfessionService.confirm(p,quote.nonce());boolean replay=false;try{ProfessionService.review(p,"materials:"+NativeSpecimens.QUEST);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&store.professions(p.getUUID()).track(Profession.MINER).xp()==3900&&store.professions(p.getUUID()).track(Profession.MINER).completedQuestIds().size()==21,"Actual four physical ore-block specimens consumed atomically for300XPonce");supply(h,p);CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("NATIVE_SPECIMEN_NATIVE_PASSED: actual marked native four ordinary-SilkI ore drops/native pickup/permanent grouped regular-deepslate delivery, stocked/placed/ordinary-tool/currentclaim/replay refusals, final-durability native tool destruction still authenticates real output/actual funded Master supply native material debit/replay/22earned4200XP; private service period5to1/raw tools/future native terrain only, no source/count/XP/quest/rank injection");h.succeed();}));}));
 }
 static void supply(GameTestHelper h,ServerPlayer p)throws Exception{var server=p.server;var store=CommerceService.store(server);var path=server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(server);var root=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(path)).getAsJsonObject();root.getAsJsonObject("goals").addProperty("kingdom_smp:miner/m06",1);java.nio.file.Files.writeString(path,new com.google.gson.Gson().toJson(root));CommissionQuestRules.clear(server);var terms=ContractRules.get(server).get("miner/daily");int before=p.getInventory().countItem(terms.item());for(int n=terms.quantity();n>0;n-=64)h.assertTrue(p.getInventory().add(new ItemStack(terms.item(),Math.min(64,n))),"Explicit raw native contract material fits");long pool=store.contractPoolSpent("daily",ContractRules.period("daily"));var quote=ContractService.review(p,"miner/daily");ContractService.confirm(p,quote.nonce());boolean replay=false;try{ContractService.confirm(p,quote.nonce());}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&p.getInventory().countItem(terms.item())==before&&store.contractPoolSpent("daily",ContractRules.period("daily"))==pool+terms.reward()&&store.commissionContractPeriods(p.getUUID(),"kingdom_smp:miner/m06")==1,"Actual material debit/finite funded mail/current Master one-purpose receipt");var earned=ProfessionService.review(p,"quest:kingdom_smp:miner/m06");ProfessionService.confirm(p,earned.nonce());h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==4200&&store.professions(p.getUUID()).track(Profession.MINER).completedQuestIds().size()==22,"Actual native funded Master service earns300XP without minting equipment");}
 static void harvest(GameTestHelper h,ServerPlayer p,BlockPos pos,boolean silk,boolean last){BlacksmithRepairRuntime.near(p,pos);var tool=new ItemStack(Items.DIAMOND_PICKAXE);if(silk)tool.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SILK_TOUCH),1);if(last)tool.setDamageValue(tool.getMaxDamage()-1);p.setItemInHand(InteractionHand.MAIN_HAND,tool);h.assertTrue(p.gameMode.destroyBlock(pos),"Native actual successful specimen break");if(last)h.assertTrue(p.getMainHandItem().isEmpty(),"Actual final-durability tool is destroyed");for(var entity:p.serverLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2))){entity.setNoPickUpDelay();entity.playerTouch(p);}}
 interface Action{void run()throws Exception;}static void guard(GameTestHelper h,Action a){try{a.run();}catch(Exception e){h.fail(e.toString());}}
}
